/* #2 dps 口径展示 + 过时提示 */
function dpsBasisInfo() {
  const m = (CFG && CFG.margin) || {};
  const basisMap = { last_fy: '上一年度实际', ttm: '滚动12个月', forward: '预期(前瞻)' };
  const basis = m.dpsBasis ? (basisMap[m.dpsBasis] || m.dpsBasis) : null;
  if (!basis) return '<span class="tx3">dps 口径：未标注</span>';
  let txt = 'dps 口径：' + basis;
  // config.meta.generated 距今 > 180 天且 last_fy → 提示可能过时
  const gen = CFG && CFG.meta && CFG.meta.generated;
  if (genreOld(gen, 180) && m.dpsBasis === 'last_fy')
    txt += ' <b class="gold">⚠ config 生成已超 6 个月，dps 可能过时，建议重跑选股脚本</b>';
  return '<span class="tx3">' + txt + '</span>';
}
function genreOld(gen, days) {
  if (!gen) return false;
  const t = Date.parse(String(gen).replace(' ', 'T'));
  return isFinite(t) && (Date.now() - t) > days * 864e5;
}

