// 分红再投资：勾选时校验买入股数/价格/日期
const reinvest = $('#inDReinvest') && $('#inDReinvest').checked && !(S.editing && S.editing.kind === 'div');
const buyShares = +($('#inDBuyShares') ? $('#inDBuyShares').value : 0) || 0;
const buyPrice = +($('#inDBuyPrice') ? $('#inDBuyPrice').value : 0) || 0;
const buyDate = ($('#inDBuyDate') && $('#inDBuyDate').value) || date;
if (reinvest) {
  if (buyShares <= 0 || buyPrice <= 0) { toast('再投资需填写买入股数和价格', true); return; }
  // #4 A股最小 100 股且整数倍；不足 100 股的分红余额不再投资（只记分红）
  if (buyShares < 100 || buyShares % 100 !== 0) { toast('买入股数须 ≥100 且为 100 的整数倍（不足部分只记分红）', true); return; }
}
try {
  if (S.editing && S.editing.kind === 'div') {
    db.run('UPDATE dividend SET acct=?,code=?,name=?,date=?,amount=?,tax=?,note=? WHERE id=?',
      [acct, code, name, date, amount, tax, note, S.editing.id]);
  } else {
    db.run('INSERT INTO dividend(acct,code,name,date,amount,tax,note) VALUES(?,?,?,?,?,?,?)',
      [acct, code, name, date, amount, tax, note]);
    if (reinvest) {
      // #14 买入日期可不同于分红日期；费用按当前费率自动算
      const amt = buyShares * buyPrice;
      const autoFee = calcFee('buy', amt);
      db.run('INSERT INTO trade(acct,code,name,side,date,shares,price,fee,note) VALUES(?,?,?,?,?,?,?,?,?)',
        [acct, code, name, 'buy', buyDate, buyShares, buyPrice, +autoFee.toFixed(2), '分红再投资（自动）']);
    }
  }
  queueSave(); readState(); render();
  $('#maskDiv').classList.remove('show');
  toast('已保存 · 分红 ' + fmt(amount, 2) + ' 元' + (reinvest ? '，并记一笔买入 ' + fmt(buyShares, 0) + ' 股' : ''));
} catch (e) { toast('保存失败：' + e.message, true); }

