  const before = pos && pos.shares > 0 ? pos.costPrice : null;
  const beforeCost = pos ? pos.cost : 0, beforeSh = pos ? pos.shares : 0;
  const afterCostPrice = (beforeSh + sh) > 0 ? (beforeCost + sh * px + fee) / (beforeSh + sh) : null;
